#  六、菜单
# ══════════════════════════════════════════════════════════════════════════════


def _flush_stdin():
    """丢掉标准输入里残留的换行。

    PyCharm / VSCode 的运行窗口在 input() 之后经常还留着上一次的 \\r\\n（回车在
    Windows 上是两个字符）。用户按一次回车「返回菜单」，菜单的 input() 立刻把那个
    残留换行读成空输入 —— 这就是「按两次回车就结束」的另一半原因。
    """
    if not IS_WIN:
        return
    try:
        import msvcrt
    except ImportError:
        return
    try:
        while msvcrt.kbhit():
            msvcrt.getwch()
    except Exception:
        pass


def wait_enter(prompt="按回车或空格返回菜单…"):
    """等一次按键：回车、空格、Esc、q 都算，不必再按一次回车。

    原来的实现是 input()，在 PyCharm 里有两个毛病：空格不算提交（按了没反应），
    而且回车会进缓冲区，被下一次菜单读取吃掉。这里在 Windows 控制台上改用
    msvcrt 逐字符读，读完再清空缓冲区，两边都堵住。
    """
    print("\n" + GRAY("  " + prompt), end="", flush=True)
    if IS_WIN and sys.stdin is not None and sys.stdin.isatty():
        try:
            import msvcrt
            while True:
                ch = msvcrt.getwch()
                if ch in ("\r", "\n", " ", "\x1b", "q", "Q"):
                    break
                if ch in ("\x00", "\xe0"):     # 方向键 / 功能键带一个前缀字节，读掉
                    msvcrt.getwch()
            print()
            _flush_stdin()
            return
        except Exception:
            pass
    try:
        input()
    except (EOFError, KeyboardInterrupt):
        pass
    print()


def menu(args):
    W = 70
    while True:
        clear_screen()
        print(BOLD(CYAN("╔" + "═" * W + "╗")))
        print(BOLD(CYAN("║")) + fit("  破甲一键通  v%s   多目标统一脚本" % VER_TAG, W) + BOLD(CYAN("║")))
        print(BOLD(CYAN("║")) + GRAY(fit("  " + FREE_LINE, W)) + BOLD(CYAN("║")))
        print(BOLD(CYAN("╠" + "═" * W + "╣")))
        for line in ("  [1] 一键破甲         ← 先选要破哪个（dsh / WorkBuddy / ZCode）",
                     "  [2] 检测状态         只读，不改任何文件",
                     "  [3] 诊断详情         逐文件列出补丁/备份状态",
                     "  [4] 预演             只显示会改什么",
                     "  [5] 选目标单打       同上，等价入口",
                     "  [6] 还原              选择目标还原成官方原版",
                     "  [7] WorkBuddy 守护    安装 / 卸载 / 查看后台守护任务",
                     "  [8] 体检（只读）      磁盘态 / 凭证 / 自证就绪，不改盘",
                     "  [9] WorkBuddy 快照    生成基准 / 与基准对比",
                     "  [u] 检查更新          只查有没有新版，查到了再问你要不要装",
                     "  [0] 退出"):
            print(BOLD(CYAN("║")) + fit(line, W) + BOLD(CYAN("║")))
        print(BOLD(CYAN("╚" + "═" * W + "╝")))
        _flush_stdin()                      # 清掉上一轮残留的换行，避免空输入直接跳过菜单
        try:
            c = input(BOLD(GREEN("  请选择 (0-9, u) > "))).strip().lstrip("\ufeff")
        except (EOFError, KeyboardInterrupt):
            print()
            return

        if c in ("0", "q", "Q", "exit", "quit"):
            return

        if not c:
            # 空输入只重画菜单，绝不退出。
            # 以前这里和 "0" 一起 return，于是 PyCharm 运行窗口里残留的一个换行
            # 就能把整个程序关掉 —— 现象就是「按两次回车，菜单一闪就结束」。
            continue

        try:
            if c == "1":
                # 先问要破哪个，绝不默认全打（破坏性操作必须由用户明确指定范围）
                sel = _pick_targets(args, "一键破甲 —— 选要处理的目标")
                if sel:
                    _confirm_and_run(args, "apply", sel)
            elif c == "2":
                run_status(args, list(DEFAULT_TARGETS))
            elif c == "3":
                args.diagnose = True
                run_status(args, list(DEFAULT_TARGETS))
                args.diagnose = False
            elif c == "4":
                sel = _pick_targets(args, "预演 —— 选要预演的目标")
                if sel:
                    if "dsh" in sel:
                        _ask_dsh_mode(args)
                        if getattr(args, "git_bash", None) is None:
                            _ask_git_bash(args)
                    run_action(args, "dry-run", sel)
            elif c == "5":
                sel = _pick_targets(args, "单打 —— 选要处理的目标")
                if sel:
                    _confirm_and_run(args, "apply", sel)
            elif c == "6":
                sel = _pick_targets(args, "还原 —— 选要还原的目标")
                if sel and _confirm("还原 %s ？这会把它们变回官方原版。" % ", ".join(sel)):
                    run_action(args, "revert", sel)
            elif c == "7":
                _guard_menu(args)
            elif c == "8":
                run_check(args)
            elif c == "9":
                _snap_menu(args)
            elif c in ("u", "U"):
                # 只查、只报，装不装再问一次 —— 菜单里不该出现「悄悄就装了」。
                ver, _assets, err = update_check()
                if err or not ver:
                    say("  检查更新失败：%s" % (err or "没读到版本号"), "y")
                elif _ver2(ver) <= _ver2(VERSION):
                    say("  已是最新（%s）" % VER_TAG, "g")
                else:
                    say("  最新发布：%s　当前：%s" % (ver, VERSION), "dg")
                    if _confirm("现在下载并安装 %s ？装完本进程退出才换文件。" % ver):
                        run_update()
            else:
                continue
        except KeyboardInterrupt:
            say("")
            continue

        wait_enter()


def _detect_quick(k, args):
    """轻量探测某个目标是否已安装（只读，绝不弹窗、绝不提问）。

    返回 (bool, 说明文字)。任何异常都当作"探测失败"，不当成"没装"，
    免得把装了的用户挡在外面。
    """
    try:
        t = TARGETS[k]()
    except Exception:
        return True, ""
    try:
        ok = bool(t.detect_ok(args))
        return ok, ("" if ok else "未检测到安装")
    except Exception:
        return True, ""


def _pick_targets(args=None, title="选目标"):
    """让用户勾选要处理的目标。返回目标 key 列表；空列表 = 用户取消。

    直接从回车 = 什么都不做（显式跳过），不再默认全选 —— 破坏性操作必须由用户明确指定范围。
    非法输入不再静默返回空，而是提示后重问。
    v7.7：目标列表由 DEFAULT_TARGETS 动态生成，加目标时这里不会漏（踩过）。
    """
    order = list(DEFAULT_TARGETS)
    label = dict(TARGET_LABEL)             # 不再写死 —— 加目标这里自动跟上
    all_key = str(len(order) + 1)          # "全部" 的序号
    # 探测结果只在第一次重绘时算，之后复用。
    # 原来 while 每轮都对 6 个目标重跑 _detect_quick —— 实测每轮 16.4 秒，
    # 输入一个非法序号要重问时用户就得再等 16 秒（对抗测试就是卡死在这）。
    det_cache = {}
    while True:
        say("")
        say("  ── %s ──────────────────────────────────────────" % title, "c")
        picked_note = {}
        for i, k in enumerate(order, 1):
            if args is None:
                ok, note = True, ""
            else:
                if k not in det_cache:
                    det_cache[k] = _detect_quick(k, args)
                ok, note = det_cache[k]
            picked_note[k] = ok
            mark = "已检测到" if ok else "未检测到"
            color = "g" if ok else "dg"
            say("    [%d] %-24s %s" % (i, label.get(k, k), mark), color)
        say("    [%s] 全部（仅对上面「已检测到」的目标生效）" % all_key)
        say("    [0] 取消 / 返回")
        say("  ──────────────────────────────────────────────────")
        try:
            c = input(BOLD(GREEN("  输入序号（可多选，如 12；直接回车 = 取消）> "))).strip().lstrip("\ufeff")
        except (EOFError, KeyboardInterrupt):
            say("")
            return []

        if c in ("0", "q", "Q", "exit", "quit"):
            return []
        if c == "":
            say("  已取消，什么都没做。", "dg")
            return []

        m = {str(i): k for i, k in enumerate(order, 1)}
        m[all_key] = "all"
        out = []
        bad = []
        for ch in c:
            if ch not in m:
                if not ch.isspace():
                    bad.append(ch)
                continue
            if m[ch] == "all":
                # 只选"已检测到"的；全都未检测到则回退到全部（避免选了却没目标可打）
                detected = [k for k in order if picked_note.get(k, True)]
                return detected or list(order)
            if m[ch] not in out:
                out.append(m[ch])
        if bad:
            say("  [!] 认不出这些输入：%s —— 只能输 1~%s 或 0。" % (" ".join(bad), all_key), "y")
            say("      请重新选择。", "dg")
            continue
        if not out:
            say("  [!] 没选中任何目标，请重新选择（或输 0 取消）。", "y")
            continue
        return out


def _confirm(text):
    try:
        return input("  %s (y/N) " % text).strip().lower() == "y"
    except (EOFError, KeyboardInterrupt):
        return False


def _ask_dsh_mode(args):
    """让用户选 DSH 的破甲方式。回车 = 注入模式（老行为，不改变默认）。"""
    say("")
    say("  DSH 破甲方式（两种，选一种）：", "c")
    say("    [1] 注入模式    改磁盘上的 persona / 免责句，所有模式都生效（默认）", "g")
    say("    [2] 破甲模式    社区特供：不改任何官方文件，只在模式下拉里多一项「破甲模式」", "g")
    say("                    选中它才生效，宿主升级也不会把人格冲掉", "g")
    say("    直接回车 = 注入模式。", "dg")
    try:
        c = input("  选择 (1/2) > ").strip()
    except (EOFError, KeyboardInterrupt):
        c = ""
    if c == "2":
        args.dsh_mode = "preset"
        say("  已选：破甲模式（社区特供）", "g")
    else:
        args.dsh_mode = "inject"
    return True


def _ask_git_bash(args):
    """Windows 上问一次：要不要把默认命令工具从 PowerShell 换成 Git Bash。

    默认否。这是改宿主行为的选项，不该悄悄打开 —— 打开后模型看到的是 bash 工具，
    写出来的命令是 bash 语法，行为跟之前完全不同，用户得知道这件事。
    """
    if not IS_WIN:
        return False
    say("")
    say("  接管 Git Bash？（Windows 可选）", "c")
    say("    官方在 Windows 上把 bash 工具关了，只剩 PowerShell。PS 5.1 的引号规则", "g")
    say("    （反引号转义、双引号里 $ 展开、没有 &&、here-string 结束符必须顶格）", "g")
    say("    对内联命令极不友好，模型经常在这儿翻车。打开这一项会把 bash 工具和", "g")
    say("    执行器一起切到 Git Bash；本机没有就现下一个 PortableGit（解压即用，", "g")
    say("    不写注册表，卸载就是删目录）。", "g")
    say("    直接回车 = 不改（保持 PowerShell）。", "dg")
    try:
        c = input("  接管 Git Bash？(y/N) ").strip().lower()
    except (EOFError, KeyboardInterrupt):
        c = ""
    args.git_bash = (c == "y")
    if args.git_bash:
        say("  已选：接管 Git Bash（重启 DSH 后生效）", "g")
    return True


def _confirm_and_run(args, mode, sel):
    say("")
    label = dict(TARGET_LABEL)             # 不再写死
    say("  目标：%s" % "、".join(label.get(k, k) for k in sel), "c")
    # 只在真的会碰 DSH 时才提 DSH 进程的事，选了别的还说就是噪声。
    if "dsh" in sel:
        say("  DSH 正在运行的进程不会被结束（要结束用 --kill-dsh）。", "dg")
        if mode != "revert":
            _ask_dsh_mode(args)
            # 命令行显式给了 --git-bash / --no-git-bash 就不再问。
            if getattr(args, "git_bash", None) is None:
                _ask_git_bash(args)
    if _confirm("确认执行？"):
        run_action(args, mode, sel)
    else:
        say("  已取消。")


def _guard_menu(args):
    t = WorkBuddyTarget()
    say("")
    say("  WorkBuddy 守护任务（每 30 分钟 + 每次登录自动重打补丁）")
    say("  [1] 查看现状   [2] 安装/重装（需管理员）   [3] 全部卸载")
    try:
        c = input("  选择 > ").strip()
    except (EOFError, KeyboardInterrupt):
        return
    if c == "1":
        names = t.scheduled_task_names()
        if not names:
            say("  当前没有任何守护任务。", "y")
        else:
            t.audit_guard_tasks(verbose=True)
    elif c == "2":
        if not is_admin():
            say("  当前不是管理员，登录守护可能装不上（每 30 分钟那个通常可以）。", "y")
        removed, failed = t.remove_guard_tasks()
        if removed:
            say("  已清理旧守护任务 %d 个" % removed, "g")
        if failed:
            say("  有 %d 个删不掉（需管理员）：%s" % (len(failed), ", ".join(failed)), "y")
        r = t.install_guard_tasks(is_admin())
        say("  守护解释器：%s" % r["python"], "dg")
        say("  每30分钟：%s" % ("已安装" if r["hourly"] else "失败"), "g" if r["hourly"] else "red")
        say("  每次登录：%s" % ("已安装" if r["logon"] else "未安装（需管理员）"), "g" if r["logon"] else "y")
        if not r.get("wellformed", True):
            say("  [!] 任务结构不对（注册了也跑不起来）：%s" % (r.get("wellformed_msg") or ""), "red")
        if r["hourly"] and not r["points_here"]:
            say("  [!] 任务已建但命令看起来没指向本脚本，请用管理员手动核对：", "red")
            say("      schtasks /Query /TN \"%s\" /XML" % TASK_HOURLY, "dg")
        for _k, _label in (("msg_hourly", "每30分钟"), ("msg_logon", "每次登录")):
            _msg = (r.get(_k) or "").strip()
            if _msg and ("ERROR" in _msg.upper() or "失败" in _msg):
                say("      %s 返回：%s" % (_label, _msg.splitlines()[0][:120]), "dg")
    elif c == "3":
        removed, failed = t.remove_guard_tasks()
        say("  已删除 %d 个守护任务" % removed, "g" if removed else "")
        if failed:
            say("  删不掉（需管理员）：%s" % ", ".join(failed), "y")


def _snap_menu(args):
    t = WorkBuddyTarget()
    say("")
    say("  [1] 生成快照（留基准）   [2] 与最新基准对比")
    try:
        c = input("  选择 > ").strip().lstrip("\ufeff")
    except (EOFError, KeyboardInterrupt):
        return
    if c == "1":
        t.do_snapshot(args)
    elif c == "2":
        t.do_compare()


#  七、运行库自检 + 入口
# ══════════════════════════════════════════════════════════════════════════════

_pause_needed = False


def _hold_screen():
    """有真终端就等一次回车，没有就立刻返回。

    打包版双击运行时控制台是本进程独占的，程序一退窗口就关，提示等于没出现。
    从 cmd / bat 里跑时窗口还在，多按一次回车纯属打扰 —— 所以只在冻结态调用。

    判据要连 stdout 一起看。图形界面冻结态会起一个 `exe --version` 子进程问版本
    号，那个子进程继承了终端的 stdin，stdout 却被管道接走；只看 stdin 的话这里就
    在等一个永远不会来的回车，父进程卡在 subprocess.run 里，界面停在横幅第一行。
    """
    try:
        if (sys.stdin and sys.stdin.isatty()
                and sys.stdout and sys.stdout.isatty()):
            input("\n按回车键退出…")
    except Exception:
        pass


def _pause_on_exit():
    if QUIET or not _pause_needed:
        return
    _hold_screen()


def check_runtime():
    if sys.version_info < (3, 8):
        print("\n[运行库错误] 需要 Python 3.8 或更高版本（当前 %d.%d.%d）。"
              % (sys.version_info.major, sys.version_info.minor, sys.version_info.micro))
        print("  下载：https://www.python.org/downloads/（安装时勾上 Add to PATH）")
        try:
            import webbrowser
            webbrowser.open("https://www.python.org/downloads/")
        except Exception:
            pass
        sys.exit(1)
    # 冻结态（单文件可执行文件）里标准库是打进包里的，没有"用户 Python 装残了"
    # 这回事；而且下面用 importlib 按名字动态导入，PyInstaller 静态分析看不见，
    # 会把 platform 之类的模块漏掉 —— 真跑起来就误报"标准库不完整"。
    if getattr(sys, "frozen", False):
        return
    missing = []
    for mod in ("os", "re", "sys", "json", "shutil", "hashlib", "subprocess",
                "argparse", "datetime", "unicodedata", "string", "platform"):
        try:
            importlib.import_module(mod)
        except Exception as e:
            missing.append("%s (%r)" % (mod, e))
    if missing:
        print("[运行库错误] 标准库不完整：" + ", ".join(missing))
        print("  请重装 Python：https://www.python.org/downloads/")
        sys.exit(1)


def _want_interactive(args, argc=None):
    """该不该进交互菜单。

    两种都算：一个参数都没有（双击 / `python 破甲一键通.py`），或者显式给了
    `--menu`。以前只看 `argc <= 1`，于是 `exe --menu` 因为长度是 2 被判成
    「非交互」，而 --menu 又不算任何动作 → 一路落到 run_status：用户想看菜单，
    结果跑了一遍检测。源码态 `python 破甲一键通.py --menu` 同样被吃掉。
    """
    if argc is None:
        argc = len(sys.argv)
    return argc <= 1 or bool(getattr(args, "menu", False))


def _cmd_name():
    """帮助与提示里怎么称呼自己。

    打包版还写 `python 破甲一键通.py`，会让人以为得先装 Python；直接给 exe 名。
    """
    base = os.path.basename(SELF)
    return base if getattr(sys, "frozen", False) else "python " + base


class _Parser(argparse.ArgumentParser):
    """参数出错时给中文提示，别把 argparse 的英文原文糊在脸上就退。

    打包版双击运行，报错后控制台可能一闪而过 —— 让提示留在屏幕上靠入口那段
    预设的暂停，这里只负责把话说清楚。
    """

    def error(self, message):
        raw = (message or "").strip()
        say("")
        if raw.startswith("unrecognized arguments"):
            # argparse 原文是 `unrecognized arguments: --xx`，照抄会让同一句出现两次
            bad = raw.split(":", 1)[-1].strip()
            say("  参数有问题：认不出 %s" % bad, "red")
            if bad and not bad.startswith("-"):
                say("    看着像文件路径 —— 参数只认 -- 开头的开关，本工具不吃拖放。", "dg")
        else:
            say("  参数有问题：%s" % raw, "red")
        say("    全部参数：%s --help" % _cmd_name(), "dg")
        say("    命令行菜单：%s --menu" % _cmd_name(), "dg")
        self.exit(2)

    def exit(self, status=0, message=None):
        """`--help`、`--version`、参数错误都从这里出去。

        打包版双击时控制台是本进程独占的，打印完直接退等于窗口一闪而过 ——
        冻结态先停一下。从 cmd / bat 里跑时 stdio 不是 tty 或窗口还在，
        `_hold_screen` 自己会立刻返回。
        """
        if message:
            sys.stderr.write(message)
        if getattr(sys, "frozen", False):
            _hold_screen()
        raise SystemExit(status)


def _epilog():
    """`--help` 底部的示例。

    表驱动而不是手写空格：打包版和源码态的命令名宽度差一大截，按显示宽度补
    空格才能对齐（中文字符占两格）。
    """
    rows = [("", "交互菜单"),
            ("--menu", "命令行交互菜单（打包版不带参数时默认开图形界面）"),
            ("--status", "只读检测所有目标"),
            ("--dry-run", "预演"),
            ("--apply", "全部打一遍"),
            ("--apply --target wb --full", "只打 WorkBuddy（含闸门/网页过滤/文件保护）"),
            ("--revert --target dsh", "只还原 DSH"),
            ("--pick dsh", "手动指定 DSH 安装目录（弹系统目录窗口）"),
            ("--pick all --clear", "清除手动指定，改回自动探测"),
            ("--guard install", "装 WorkBuddy 守护任务")]
    cmd = _cmd_name()
    lines = ["示例："]
    for arg, desc in rows:
        head = (cmd + " " + arg).strip()
        lines.append("  " + head + " " * max(2, 52 - dwidth(head)) + desc)
    return "\n".join(lines) + "\n"


def build_parser():
    p = _Parser(
        description="破甲一键通 v%s —— %s，共 %d 个目标一键破甲"
                    % (VER_TAG, " / ".join(TARGET_LABEL[k] for k in DEFAULT_TARGETS),
                       len(DEFAULT_TARGETS)),
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog=_epilog())
    p.add_argument("--target", default="all", help="all|dsh|wb|zcode|codex|cursor|claude，可逗号分隔（默认 all）")
    p.add_argument("--status", action="store_true", help="只读：检测所有目标")
    p.add_argument("--update", action="store_true", help="检查并安装新版本")
    p.add_argument("--check-update", dest="check_update", action="store_true",
                   help="只检查有没有新版本")
    p.add_argument("--no-update-check", dest="no_update_check", action="store_true",
                   help="启动时不查更新（默认只查一次、只提示，从不自动安装）")
    p.add_argument("--diagnose", action="store_true", help="只读：详细取证")
    p.add_argument("--check", action="store_true",
                   help="只读体检：磁盘态 / 明文凭证提示 / 自证就绪（绝不改盘，有问题退出码 1）")
    p.add_argument("--dry-run", action="store_true", help="预演，不改盘")
    p.add_argument("--apply", action="store_true", help="执行破甲")
    p.add_argument("--revert", action="store_true", help="还原（DSH/WorkBuddy 从备份还原）")
    p.add_argument("--restore", action="store_true", help="同 --revert（兼容原工具写法）")
    p.add_argument("--full", action="store_true", help="WorkBuddy 完全破甲：+网页过滤 +Ask模式 +文件保护中和")
    p.add_argument("--nofileguard", action="store_true", help="只中和文件保护")
    p.add_argument("--ask-mode", action="store_true", dest="ask_mode", help="解除 Ask 模式只读限制")
    p.add_argument("--web-filter", action="store_true", dest="web_filter", help="去掉网页内容安全过滤")
    p.add_argument("--guard", choices=["install", "remove", "status"], help="WorkBuddy 守护任务管理")
    p.add_argument("--snapshot", action="store_true", help="生成 WorkBuddy 提示词快照")
    p.add_argument("--compare", action="store_true", help="与最新 WorkBuddy 快照对比")
    p.add_argument("--purge-spill", action="store_true", dest="purge_spill",
                   help="清掉全部会话快照（含未过期的；不在备份范围内，删了还原不回来）")
    p.add_argument("--clean-spill", action="store_true", dest="clean_spill",
                   help="只清 24 小时以前的过期会话快照（默认只统计不删）")
    p.add_argument("--keep-cache", action="store_true", dest="keep_cache", help="不删运行时缓存")
    p.add_argument("--restart-wb", action="store_true", dest="restart_wb", help="破甲后重启 WorkBuddy")
    p.add_argument("--kill-dsh", action="store_true", dest="kill_dsh",
                   help="允许结束正在跑的 DSH 进程（默认禁止！）")
    p.add_argument("--force", action="store_true",
                   help="已破甲的目标也强制重写成统一版本（统一人格哈希）")
    p.add_argument("--persona", help="人格文件（默认脚本目录 persona.md）")
    p.add_argument("--persona-name", metavar="NAME", default=None,
                   help="内置人格的称呼（默认「" + DEFAULT_PERSONA_NAME + "」）。"
                        "写进 状态/人格称呼.txt，之后每次 --apply 自动沿用；"
                        "也可用环境变量 POJIA_NAME。换称呼是为了不留下固定特征串")
    p.add_argument("--persona-list", action="store_true",
                   help="只读：列出人格库（人格库/）里的片段与当前启用的组合")
    p.add_argument("--persona-set", metavar="NAMES", default=None,
                   help="设定启用的人格组合（逗号分隔，按顺序拼接；给空串=清空。"
                        "写进 状态/persona-set.json，之后每次 --apply 自动沿用）")
    p.add_argument("--persona-show", action="store_true",
                   help="只读：打印当前组合编译后的最终人格文本")
    p.add_argument("--persona-explain", action="store_true",
                   help="只读：分层解释人格来源（每段字节 / SHA256 / 插值变量 / 总大小）")
    p.add_argument("--pick", metavar="TARGET",
                   help="弹系统目录选择窗口，手动指定某个目标的安装位置并记住"
                        "（" + " / ".join(list(TARGETS)) + "）")
    p.add_argument("--clear", action="store_true",
                   help="配合 --pick 用：清除记住的手动路径，改回自动探测")
    p.add_argument("--dsh-dir", help="手动指定 @deepseek-ai 目录或 DSH Desktop 根")
    p.add_argument("--deep", action="store_true",
                   help="还原时连没有标记的 resources/app/ 解包目录一起删（早期版本解的目录没有标记，不删就等于没还原）")
    p.add_argument("--dsh-mode", dest="dsh_mode", choices=["inject", "preset"], default="inject",
                   help="DSH 破甲方式：inject=改磁盘文件（默认）；"
                        "preset=只注册「破甲模式」预设（社区特供，不改任何官方文件，"
                        "在模式下拉里选中才生效）")
    p.add_argument("--git-bash", dest="git_bash", action="store_true", default=None,
                   help="Windows：接管 Git Bash —— 把 DSH 的 bash 工具与执行器打开并指向 Git Bash，"
                        "替掉 PowerShell。本机没有就现下一个 PortableGit（解压即用，不写注册表）")
    p.add_argument("--no-git-bash", dest="git_bash", action="store_false",
                   help="不改 Git Bash 接管（默认；交互时也不再问）")
    p.add_argument("--zcode-dir", help="手动指定 ZCode 配置目录（一般是 用户目录\\.zcode）")
    p.add_argument("--mac-check", dest="mac_check", nargs="?", const="", metavar="APP",
                   help="macOS：检查这些 .app 的代码签名还完整吗（不传路径就扫 /Applications "
                        "和 ~/Applications）。破甲往 .app 里写过文件后签名会失效，带隔离标记的"
                        "包再启动会报「已损坏，无法打开」")
    p.add_argument("--resign", action="store_true",
                   help="配合 --mac-check：对签名失效的包做 ad-hoc 重签"
                        "（codesign --force --deep --sign -，会顶掉厂商签名）")
    p.add_argument("--zcode-cjs", help="手动指定 ZCode 的 resources\\glm\\zcode.cjs（自定义安装路径时用）")
    p.add_argument("--zpatch", action="store_true",
                   help="额外替换 ZCode 打包文件里的系统提示词（resources\\glm\\zcode.cjs；"
                        "默认关闭。会先备份 + node 语法校验，校验不过自动回滚）")
    p.add_argument("--wb-install", help="手动指定 WorkBuddy 安装目录")
    p.add_argument("--wb-data", help="手动指定 WorkBuddy 数据目录（.workbuddy）")
    p.add_argument("--wbintl-install", help="手动指定 WorkBuddy 国际版安装目录（WorkBuddyAI.exe 那层）")
    p.add_argument("--wbintl-data", help="手动指定国际版数据目录（.workbuddy-ai）")
    p.add_argument("--codex-dir", help="手动指定 Codex 配置目录（一般是 用户目录\\.codex）")
    p.add_argument("--cursor-dir", help="手动指定 Cursor 配置目录（一般是 用户目录\\.cursor）")
    p.add_argument("--claude-dir", help="手动指定 Claude 配置目录（一般是 用户目录\\.claude）")
    p.add_argument("--yes", "-y", action="store_true", help="非交互，不二次确认")
    p.add_argument("--quiet", action="store_true",
                   help="静默（守护任务用）：等价于 --apply --yes；--target 未指定或为 all 时只打 wb，"
                        "要连国际版一起守就写 --target wb,wbintl")
    p.add_argument("--version", action="version", version="破甲一键通 " + VER_TAG)
    p.add_argument("--gui", action="store_true",
                   help="打开图形界面（本机网页 UI，零依赖）")
    p.add_argument("--menu", action="store_true",
                   help="打包版双击进来默认开图形界面；加这个走命令行交互菜单")
    p.add_argument("--pause", action="store_true",
                   help="跑完停一下等回车（快捷方式里预置参数时用；--quiet 下无效）")
    # 位置参数只有一个用途：接住「把文件拖到 exe 图标上」这种误操作。不给它
    # 注册的话，拖进来的路径会变成 unrecognized arguments，用户看到的是一串
    # 英文报错 + 闪退，完全猜不到发生了什么。
    p.add_argument("files", nargs="*", metavar="文件", help=argparse.SUPPRESS)
    # 每个标记块目标都有自己的 --<key>-dir。以前只显式注册了 codex / cursor / claude
    # 三个，其余十个在提示里写着「用 --cline-dir 指定」，实际根本没注册 —— 用户照着
    # 敲就撞 unrecognized arguments，越按提示走越进不去。这里按 TARGETS 兜底补齐，
    # 以后加目标自动就有参数，不会再漏。
    _have = set()
    for _a in p._actions:
        for _o in _a.option_strings:
            _have.add(_o.lstrip("-").replace("-", "_"))
    for _k in DEFAULT_TARGETS:
        _dest = getattr(TARGETS[_k], "arg_name", "")
        if not _dest or _dest in _have:
            continue
        p.add_argument("--" + _dest.replace("_", "-"), dest=_dest,
                       help="手动指定 %s 的配置目录" % TARGET_LABEL.get(_k, _k))
    return p


def _gui_source_path():
    """找图形界面的源码文件。

    源码态：和本脚本同目录。冻结态：打包时 `破甲GUI.py` 是当**数据文件**塞进包里
    的（PyInstaller 的 `--add-data`），解包后落在 `sys._MEIPASS` 下 —— onefile 的
    临时目录，进程活着期间一直在。
    """
    cands = []
    _mp = getattr(sys, "_MEIPASS", "")
    if _mp:
        cands.append(os.path.join(_mp, "破甲GUI.py"))
    cands.append(os.path.join(HERE, "破甲GUI.py"))
    for c in cands:
        if os.path.isfile(c):
            return c
    return ""


def _launch_gui():
    """起图形界面，成功起来返回 True。

    源码态：把同目录的 破甲GUI.py 当**独立进程**拉起 —— GUI 崩了不牵连主程序。

    冻结态：包里没有解释器可拉，改用 runpy 在**当前进程**里跑。为什么不重新拉一个
    自己的 exe？单文件包每次启动都要把十几 MB 解开一遍（约一秒），而 GUI 本来就要
    占住主线程直到用户关窗口，多起一个进程纯属白等。
    """
    gui = _gui_source_path()
    if not gui:
        say("  找不到 破甲GUI.py，图形界面不可用。", "red")
        if getattr(sys, "frozen", False):
            say("  这个产物打包时没带图形界面（构建漏了 --add-data），换个官方产物。", "y")
        return False
    if getattr(sys, "frozen", False):
        import runpy
        say("  已启动图形界面，浏览器会自动打开；关掉窗口或按 Ctrl+C 即退出。", "g")
        try:
            runpy.run_path(gui, run_name="__main__")
        except SystemExit:                       # GUI 正常退出走的就是这条
            pass
        except Exception as e:
            say("  图形界面异常退出：%s" % e, "red")
            return False
        return True
    try:
        subprocess.Popen([sys.executable, gui], cwd=os.path.dirname(gui))
        say("  已启动图形界面，浏览器会自动打开；关掉那个窗口即退出。", "g")
        return True
    except OSError as e:
        say("  启动失败：%s" % e, "red")
        return False


def _default_to_gui(args):
    """双击打包版（一个参数都没有）默认开图形界面。

    打包版的使用者大多不是命令行用户：双击 exe 先看到一屏 ASCII 菜单和免责声明，
    是反的。所以冻结态 + 无参数 → 直接开界面，菜单留 `--menu`。

    源码态不受影响：`python 破甲一键通.py` 还是交互菜单（开发和脚本都在用）。
    """
    return (bool(getattr(sys, "frozen", False))
            and len(sys.argv) <= 1
            and not getattr(args, "menu", False))


# ══════════════════════════════════════════════════════════════════════════════
#  人格库 CLI（--persona-list / --persona-set / --persona-show / --persona-explain）
# ══════════════════════════════════════════════════════════════════════════════


def _persona_explain(args):
    """逐层列出来源与体积，最后给编译结果。只读，不改任何盘。"""
    say("")
    say(BOLD("人格编译解释（只读）"))
    say(GRAY("  优先级：--persona > 人格集 > persona.md > my-prompt.txt > 内置默认"))
    say("")
    cur = persona_conf_get()
    picked = ""

    def _row(tag, label, txt, err=""):
        if err:
            say("  %s %-24s %s" % (tag, label, err), "red")
            return 0
        if not txt:
            say("  %s %-24s %s" % (tag, label, "空 / 只有注释"), "dg")
            return 0
        raw = txt.encode("utf-8")
        say("  %s %-24s %7d B   sha256 %s"
            % (tag, label, len(raw), hashlib.sha256(raw).hexdigest()[:12]))
        return len(raw)

    if args.persona:
        txt, err = persona_read(os.path.abspath(args.persona))
        if _row("①", "--persona " + os.path.basename(args.persona), txt, err):
            picked = "①"
    else:
        say("  %s %-24s %s" % ("①", "--persona", "未指定"), "dg")

    if cur:
        body, parts = persona_compose(cur, "DSH")
        for nm, n, note in parts:
            if n:
                say("  %s %-24s %7d B" % ("②", "人格集:" + nm, n))
            else:
                say("  %s %-24s %s" % ("②", "人格集:" + nm, "跳过：" + note), "red")
        if body and not picked:
            picked = "②"
    else:
        say("  %s %-24s %s" % ("②", "人格集", "未启用"), "dg")

    for tag, label, path in (("③", "persona.md", PERSONA_FILE),
                             ("④", "my-prompt.txt", LEGACY_PROMPT)):
        if not os.path.isfile(path):
            say("  %s %-24s %s" % (tag, label, "不存在"), "dg")
            continue
        txt, err = persona_read(path)
        if _row(tag, label, txt, err) and not picked:
            picked = tag

    say("  %s %-24s %s" % ("⑤", "内置默认", "永远可用（空人格 + 内置政策）"), "dg")

    user, src = load_user_persona(args.persona or "", target="DSH")
    raw = user.encode("utf-8")
    allvars = persona_vars("DSH")
    # 变量要从**插值前**的原文里找：编译结果里 {{...}} 早被替换掉了，
    # 在结果上 finditer 只会永远返回空（这个坑踩过一次）。
    _origin = ""
    for _nm in cur:
        for _ext in (".md", ".txt"):
            _p = os.path.join(PERSONA_DIR, _nm + _ext)
            if os.path.isfile(_p):
                _t, _e = persona_read(_p)
                _origin += (_t or "")
                break
    if args.persona and os.path.isfile(args.persona):
        _t, _e = persona_read(os.path.abspath(args.persona))
        _origin += (_t or "")
    used = sorted(set(m.group(1) for m in PERSONA_VAR_RE.finditer(_origin))) if _origin else []
    unknown = [v for v in used if v not in allvars]
    say("")
    say(BOLD("  编译结果"))
    say("    命中层   : %s" % (picked or "⑤"))
    say("    实际来源 : %s" % src)
    say("    文本体积 : %d B（%d 字）" % (len(raw), len(user or "")))
    say("    SHA256   : %s" % (hashlib.sha256(raw).hexdigest() if raw else "(空)"))
    if used:
        say("    已插值   : %s" % ", ".join("{{%s}}" % v for v in used if v in allvars), "c")
    if unknown:
        say("    未识别   : %s（原样保留）" % ", ".join("{{%s}}" % v for v in unknown), "y")
    say(GRAY("    注意：插值在写盘那一刻求值。我们是静态改模板、不是运行时钩子，"))
    say(GRAY("          {{date}} 这类不会随会话刷新 —— 要刷新就再跑一次 --apply。"))
    return 0


def run_persona(args):
    """人格相关开关的实现。返回进程退出码（0 成功 / 1 有问题）。"""
    acted = False
    rc = 0

    # 称呼：只写本项目自己的配置文件，不碰任何客户端。
    if getattr(args, "persona_name", None) is not None:
        nm = (args.persona_name or "").strip()
        try:
            os.makedirs(STATE_DIR, exist_ok=True)
            if nm:
                with open(PERSONA_NAME_FILE, "w", encoding="utf-8", newline="\n") as _f:
                    _f.write(nm)
                globals()["_PERSONA_NAME_OVERRIDE"] = nm
            else:
                if os.path.isfile(PERSONA_NAME_FILE):
                    os.remove(PERSONA_NAME_FILE)
                globals()["_PERSONA_NAME_OVERRIDE"] = ""
            got = persona_name()
            if nm and got != nm:
                say("[!] 称呼「%s」不可用：限 16 字符内、不含引号/尖括号/反斜杠/控制字符。" % nm, "red")
                say("    当前生效的是「%s」。" % got, "y")
                rc = 1
            else:
                say("[OK] 内置人格称呼：%s" % got, "g")
                say("     之后每次 --apply 自动沿用；恢复默认用 --persona-name \"\"", "dg")
        except Exception as _e:
            say("[!] 写称呼失败：%s" % _e, "red")
            rc = 1
        acted = True

    # 唯一的写操作：只写本项目自己的配置，不碰任何客户端文件。
    if args.persona_set is not None:
        raw = (args.persona_set or "").strip()
        names = [x for x in re.split(r"[,;+\s]+", raw) if x]
        clean_names, missing = [], []
        for nm in names:
            nm = os.path.splitext(nm)[0]
            if any(os.path.isfile(os.path.join(PERSONA_DIR, nm + ext)) for ext in (".md", ".txt")):
                if nm not in clean_names:
                    clean_names.append(nm)
            else:
                missing.append(nm)
        if missing:
            say("[!] 人格库里没有这些片段：%s" % ", ".join(missing), "red")
            say("    已有的用 --persona-list 看；片段放这里：%s" % PERSONA_DIR, "y")
            rc = 1
        ok, err = persona_conf_set(clean_names)
        if not ok:
            say("[!] 写配置失败：%s（%s）" % (err, PERSONA_CONF), "red")
            return 1
        if clean_names:
            say("[OK] 已启用人格组合：%s" % " + ".join(clean_names), "g")
            say("     之后每次 --apply 自动沿用；清空用 --persona-set \"\"", "dg")
        else:
            say("[OK] 已清空人格组合，回到 persona.md / 内置默认。", "g")
        acted = True

    if args.persona_list:
        lib = persona_library()
        cur = persona_conf_get()
        say("")
        say(BOLD("人格库  %s" % PERSONA_DIR))
        if not os.path.isdir(PERSONA_DIR):
            say("  （目录还不存在，--persona-set 的片段要放进去）", "dg")
        elif not lib:
            say("  （空）", "dg")
        for nm, p, size in lib:
            mark = CYAN("●") if nm in cur else " "
            say("  %s %-20s %8d B   %s" % (mark, nm, size, os.path.basename(p)))
        say("")
        if cur:
            say("  当前组合：%s" % " + ".join(cur), "c")
        else:
            say("  当前组合：（未启用，走 persona.md 或内置默认）", "dg")
        say("  用法：--persona-set \"名字1,名字2\"   顺序即拼接顺序", "dg")
        say("        片段是普通 UTF-8 文本；可用 {{target}} {{date}} {{os}} {{hostname}} 等变量", "dg")
        acted = True

    if args.persona_show:
        user, src = load_user_persona(args.persona or "", target="DSH")
        say("")
        say(GRAY("── 来源：%s；%d 字节 ──"
                 % (src, len((user or "").encode("utf-8")))))
        say(user if user else "（空 —— 只用内置政策）")
        acted = True

    if args.persona_explain:
        rc = _persona_explain(args) or rc
        acted = True

    if not acted:
        say("--persona-list / --persona-set / --persona-show / --persona-explain 选一个用", "y")
    return rc


# ---- 自动更新 ---------------------------------------------------------------
# 发布在 GitHub Releases。检查只读 latest，安装只下当前平台那一个资产，下完先按
# 同批的 SHA256SUMS.txt 校验再换文件。换的动作必须等主进程退出（Windows 上运行中
# 的 exe 不能覆盖），所以 Windows 走一个批处理；POSIX 直接 os.replace。
#
# **从不静默安装。** 启动时只查一次「有没有新版」（`update_hint`），只读 GitHub
# 公开的 releases/latest，不带任何本机信息，结果缓存一天；不下载、不替换、不重启。
# 真升级必须用户自己敲 --update。不想让它联网：--no-update-check 或
# 环境变量 POJIA_NO_UPDATE_CHECK=1。
UPDATE_API = REPO_URL.replace("https://github.com/", "https://api.github.com/repos/") + "/releases/latest"

# 安装程序写在 HKCU 的登记项。绿色版没有这条。
INSTALL_KEY = r"Software\Mladery\pojia-ce"


def installed_mode():
    """当前进程是不是「装出来的」。

    安装版在 HKCU 留一条 InstallDir，值就是安装目录；裸 exe 走到哪都能跑，没有
    这条。判定用目录比对而不是 exe 名 —— 有人把装好的 exe 复制到桌面，那份仍该
    按绿色版处理（否则升级会去下安装包，反而把桌面那份覆盖掉）。
    """
    if os.name != "nt":
        return False
    try:
        import winreg
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, INSTALL_KEY) as k:
            d = str(winreg.QueryValueEx(k, "InstallDir")[0] or "")
    except Exception:
        return False
    if not d:
        return False
    try:
        return os.path.normcase(os.path.abspath(d)) == os.path.normcase(HERE)
    except Exception:
        return False


def update_asset():
    """当前平台该下哪个资产。

    Windows 分两种形态：装出来的下 setup.exe（静默覆盖，顺带刷新卸载项里的版本
    号），绿色版下裸 exe（换掉自身即可）。两者不能混 —— 拿裸 exe 去覆盖安装目录，
    控制面板里看到的版本会永远停在旧值。
    """
    if os.name == "nt":
        if installed_mode():
            return "pojia-ce-windows-x64-setup.exe"
        return "pojia-ce-windows-x64.exe"
    if IS_MAC:
        return ("pojia-ce-macos-arm64" if platform.machine().lower() in ("arm64", "aarch64")
                else "pojia-ce-macos-x64")
    return "pojia-ce-linux-x64"


def _ver2(s):
    """'v8.62-CE' / '8.62' -> (8, 62)。认不出来当 0.0。"""
    m = re.search(r"(\d+)\.(\d+)", str(s or ""))
    return (int(m.group(1)), int(m.group(2))) if m else (0, 0)


def update_check(timeout=8):
    """查最新发布。返回 (版本, 资产名→下载地址, 错误说明)。"""
    try:
        d = json.loads(_http_get(UPDATE_API, timeout=timeout).decode("utf-8", "replace"))
    except Exception as e:
        return "", {}, "%s" % e
    ver = str(d.get("tag_name") or "").lstrip("vV").split("-")[0]
    assets = {}
    for a in d.get("assets") or []:
        assets[str(a.get("name"))] = str(a.get("browser_download_url") or "")
    return ver, assets, ""


def update_download(assets, dst):
    """下当前平台资产并校验。返回 (ok, 说明)。"""
    name = update_asset()
    url = assets.get(name)
    if not url:
        return False, "这次发布里没有 %s" % name
    try:
        blob = _http_get(url, timeout=180)
    except Exception as e:
        return False, "下载失败：%s" % e
    want = ""
    sums = assets.get("SHA256SUMS.txt")
    want, have_table = "", False
    if sums:
        try:
            for line in _http_get(sums, timeout=20).decode("utf-8", "replace").splitlines():
                parts = line.split()
                # 构建脚本是 `sha256sum ./*`，条目写的是 `hash  ./文件名`；只比
                # 文件名的话会一条都对不上，然后静默跳过校验 —— 那等于没校验。
                if len(parts) == 2 and os.path.basename(parts[1].lstrip("*")) == name:
                    want = parts[0].lower()
                    break
            have_table = True
        except Exception:
            want = ""
    got = hashlib.sha256(blob).hexdigest()
    if want and got != want:
        return False, "校验不符（发布方 %s…，本地 %s…）" % (want[:12], got[:12])
    if have_table and not want:
        return False, "校验和表里没有 %s，不装" % name
    try:
        tmp = dst + ".part"
        with open(tmp, "wb") as f:
            f.write(blob)
        if os.name != "nt":
            os.chmod(tmp, 0o755)
        os.replace(tmp, dst)
    except Exception as e:
        return False, "写盘失败：%s" % e
    return True, "%s（%d KB%s）" % (name, len(blob) // 1024, "" if want else "，无校验和可比")


def update_install(new_path):
    """用新文件换掉当前 exe。返回 (ok, 说明)。"""
    me = os.path.abspath(SELF)
    if not getattr(sys, "frozen", False):
        return False, "源码运行时只提示不替换，新版留着：%s" % new_path
    if os.name != "nt":
        try:
            os.replace(new_path, me)
            return True, "已替换，重新运行就是新版"
        except Exception as e:
            return False, "替换失败：%s" % e
    if installed_mode():
        return _install_via_setup(new_path)
    bat = os.path.join(HERE, "_update.bat")
    lines = [
        "@echo off",
        "ping -n 4 127.0.0.1 >nul",
        ":wait",
        'move /y "%s" "%s.old" >nul 2>&1' % (me, me),
        "if errorlevel 1 (ping -n 2 127.0.0.1 >nul & goto wait)",
        'move /y "%s" "%s" >nul' % (new_path, me),
        'start "" "%s"' % me,
        'del "%~f0"',
    ]
    try:
        # cmd 读的是 OEM 代码页，用 mbcs 写。按解释器里有没有这个 codec 选，不看
        # os.name —— 用例会在 Linux 上把这套流程跑一遍。
        try:
            codecs.lookup("mbcs")
            enc = "mbcs"
        except LookupError:
            enc = "utf-8"
        with open(bat, "w", encoding=enc, errors="replace", newline="") as f:
            f.write("\r\n".join(lines) + "\r\n")
        flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        subprocess.Popen(["cmd", "/c", bat], close_fds=True, creationflags=flags)
        return True, "已安排替换，本进程退出后自动换装并重启"
    except Exception as e:
        return False, "安排替换失败：%s" % e


def _install_via_setup(setup_path):
    """安装版的自更新：等本进程退出，静默跑一遍 setup，再把程序拉起来。

    不能像绿色版那样直接 move 覆盖：onedir 的 `_internal\\*.dll` 在进程活着时
    是被锁住的，硬覆盖必然失败。用进程名轮询等它真退（按实际文件名等，用户改过
    名也认得），再让安装程序铺回原目录 —— 安装程序从注册表读 InstallDir，装完
    顺带把卸载项里的 DisplayVersion 刷新成新版本。
    """
    bat = os.path.join(HERE, "_update.bat")
    exe_name = os.path.basename(os.path.abspath(SELF))
    lines = [
        "@echo off",
        "ping -n 4 127.0.0.1 >nul",
        ":wait",
        'tasklist /fi "imagename eq %s" 2>nul | find /i "%s" >nul' % (exe_name, exe_name),
        "if not errorlevel 1 (ping -n 2 127.0.0.1 >nul & goto wait)",
        'start /wait "" "%s" /S' % setup_path,
        'start "" "%s"' % os.path.join(HERE, exe_name),
        'del "%~f0"',
    ]
    try:
        try:
            codecs.lookup("mbcs")
            enc = "mbcs"
        except LookupError:
            enc = "utf-8"
        with open(bat, "w", encoding=enc, errors="replace", newline="") as f:
            f.write("\r\n".join(lines) + "\r\n")
        flags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        subprocess.Popen(["cmd", "/c", bat], close_fds=True, creationflags=flags)
        return True, "已安排静默安装，本进程退出后自动升级并重启"
    except Exception as e:
        return False, "安排安装失败：%s" % e


def run_update(check_only=False):
    """检查（并可选安装）更新。返回退出码。"""
    ver, assets, err = update_check()
    if err:
        say("  检查更新失败：%s" % err, "y")
        return 1
    if not ver:
        say("  这次发布没读到版本号", "y")
        return 1
    say("  最新发布：%s　当前：%s" % (ver, VERSION), "dg")
    if _ver2(ver) <= _ver2(VERSION):
        say("  已是最新", "g")
        return 0
    if check_only:
        say("  有新版本。升级：%s --update" % _cmd_name(), "y")
        return 0
    dst = os.path.join(HERE, "_update_" + update_asset())
    ok, msg = update_download(assets, dst)
    if not ok:
        say("  %s" % msg, "red")
        try:
            os.path.exists(dst) and os.remove(dst)
        except Exception:
            pass
        return 1
    say("  已下载 %s" % msg, "g")
    ok, msg = update_install(dst)
    say("  %s" % msg, "g" if ok else "red")
    return 0 if ok else 1


def update_hint(args=None):
    """启动时看一眼有没有新版，只提示、不安装。

    请求的是 GitHub 公开的 releases/latest：不带任何本机信息、不带标识、不发
    query，只读回一个 JSON。结果缓存一天（状态/_update.json），不然每次开都多
    几百毫秒，还得罪一遍限流。没网、限流、被墙一律安静跳过。

    不想让它联网：`--no-update-check` 或环境变量 `POJIA_NO_UPDATE_CHECK=1`。
    """
    if os.environ.get("POJIA_NO_UPDATE_CHECK"):
        return
    if args is not None and getattr(args, "no_update_check", False):
        return
    path = os.path.join(STATE_DIR, "_update.json")
    now = time.time()
    ver = ""
    try:
        if os.path.isfile(path):
            with open(path, encoding="utf-8") as f:
                d = json.load(f)
            if now - float(d.get("t") or 0) < 86400:
                ver = str(d.get("ver") or "")
    except Exception:
        ver = ""
    if not ver:
        try:
            ver, _a, err = update_check(timeout=3)
        except Exception:
            return
        if err or not ver:
            return
        try:
            os.makedirs(STATE_DIR, exist_ok=True)
            with open(path, "w", encoding="utf-8") as f:
                json.dump({"t": now, "ver": ver}, f)
        except Exception:
            pass
    if _ver2(ver) <= _ver2(VERSION):
        return
    say("", "")
    say("  有新版本 %s（当前 %s）。升级：%s --update" % (ver, VERSION, _cmd_name()), "y")


def main():
    global QUIET, _pause_needed, READONLY
    check_runtime()
    _init_console()

    args = build_parser().parse_args()
    if getattr(args, "files", None):
        # 拖到图标上想「用这个工具打开它」——本工具没有这个用法，直说。
        say("")
        say("  带进来的文件：%s" % "  ".join(args.files[:5]), "y")
        say("  这是命令行工具的参数入口，不接受拖放文件。", "dg")
        say("  直接双击 → 图形界面；命令行菜单 → %s --menu" % _cmd_name(), "dg")
        return
    if getattr(args, "gui", False):
        _launch_gui()
        _pause_needed = False              # 界面已经拦了一道，关掉后不必再按回车
        return
    # 双击打包版进来（没有任何参数）先开界面；起不来（包里没带 GUI）就落到菜单，
    # 别让用户对着一个空控制台。
    if _default_to_gui(args) and _launch_gui():
        _pause_needed = False
        return
    if args.quiet:
        QUIET = True

    # 人格库子命令。list/show/explain 打印完就退出；--persona-set 只改本项目自己的
    # 配置。要是在同一条命令里还给了 --apply / --revert / --status，就先定组合再
    # 往下走（顺序很重要：配置写完，本轮 apply 才能读到新组合）。
    if (getattr(args, "persona_list", False) or getattr(args, "persona_show", False)
            or getattr(args, "persona_explain", False)
            or getattr(args, "persona_name", None) is not None
            or getattr(args, "persona_set", None) is not None):
        _prc = run_persona(args)
        if not (args.apply or args.revert or args.dry_run or args.status):
            return _prc

    if args.restore:
        args.revert = True
    args.full = args.full or False

    if args.update or args.check_update:
        rc = run_update(check_only=bool(args.check_update and not args.update))
        _pause_needed = bool(getattr(args, "pause", False)) and not QUIET
        return rc

    interactive = _want_interactive(args)
    # 菜单退出后不必再按一次回车（菜单里已经 wait_enter 过）；--pause 才留屏。
    _pause_needed = bool(getattr(args, "pause", False)) and not QUIET

    # 只查「有没有新版」，不下载、不安装；--no-update-check 可整个关掉。
    if interactive and not QUIET:
        update_hint(args)
    say("")
    header("一套人格 · 一个脚本",
           " / ".join(TARGET_LABEL[k] for k in DEFAULT_TARGETS))
    say("")
    say(GRAY("  ── 免责声明 ──────────────────────────────────────────"))
    for _dl in DISCLAIMER_LINES:
        say("  " + _dl)
    say(GRAY("  ──────────────────────────────────────────────────────"))
    say("")

    # ---- 只剩只读/工具类动作 ----
    if args.snapshot:
        WorkBuddyTarget().do_snapshot(args)
        return
    if args.compare:
        WorkBuddyTarget().do_compare()
        return
    if args.mac_check is not None:
        # macOS 签名体检。nargs="?"：不带值扫 /Applications，带值就查指定路径。
        # 这条是纯只读，除非再给 --resign。
        _p = (args.mac_check or "").strip()
        run_mac_check(args, [_p] if _p else None)
        return
    if args.guard:
        t = WorkBuddyTarget()
        if args.guard == "status":
            # `--guard status` 是纯查询，同样不许往脚本目录写日志。
            #   install / remove 是改动作，照旧落日志（那正该留痕）。
            READONLY = True
            t.audit_guard_tasks(verbose=True)
        elif args.guard == "install":
            if not is_admin():
                say("  当前不是管理员，登录守护可能装不上。", "y")
            removed, failed = t.remove_guard_tasks()
            if removed:
                say("  已清理旧守护任务 %d 个" % removed, "g")
            r = t.install_guard_tasks(is_admin())
            say("  每30分钟：%s   每次登录：%s" % ("已安装" if r["hourly"] else "失败",
                                                 "已安装" if r["logon"] else "未安装"))
            if not r.get("wellformed", True):
                say("  [!] 任务虽已注册，但结构不对（跑不起来）：%s"
                    % (r.get("wellformed_msg") or "命令格式异常"), "red")
                say("      请用管理员身份重跑 --guard install", "y")
            for _k, _label in (("msg_hourly", "每30分钟"), ("msg_logon", "每次登录")):
                _msg = (r.get(_k) or "").strip()
                if _msg and ("ERROR" in _msg.upper() or "失败" in _msg):
                    say("      %s 返回：%s" % (_label, _msg.splitlines()[0][:120]), "dg")
            if not r["logon"] and not is_admin():
                say("      登录任务需要管理员权限才能注册：右键脚本 → 以管理员身份运行，"
                    "再执行 --guard install", "dg")
            if not r["points_here"]:
                say("  [!] 任务命令没指向本脚本，请核对：schtasks /Query /TN \"%s\" /XML" % TASK_HOURLY, "y")
        else:
            removed, failed = t.remove_guard_tasks()
            say("  已删除 %d 个守护任务" % removed, "g" if removed else "")
        return

    # ---- 手动指定安装目录（弹系统目录选择窗口） ----
    if args.clear and not args.pick:
        say("  --clear 要配合 --pick 一起用，例如： --pick dsh --clear", "y")
        return
    if args.pick:
        spec = (args.pick or "").strip().lower()
        if args.clear:
            if spec in ("all", "*", ""):
                clear_manual_path()
                say("  已清除全部手动指定的目录，改回自动探测。", "g")
            else:
                for k in resolve_targets(args.pick):
                    clear_manual_path(k)
                    say("  已清除 %s 的手动指定，改回自动探测。" % TARGETS[k]().label, "g")
            return
        if QUIET:
            say("  --quiet（守护任务模式）下不会弹窗，跳过。", "y")
            return
        for k in resolve_targets(args.pick):
            do_ask_pick(TARGETS[k](), args)
        return

    # ---- 守护任务静默调用：直接跑标准破甲 ----
    # 原来无条件把 target 压成 "wb"，于是守护任务永远护不到国际版 ——
    # 命令行写 `--quiet --target wbintl` 也会被这句覆盖回去，用户以为设了其实没设。
    # 现在只在没指定（默认 all）时才回落 wb；显式给了 target 就照给的来。
    if args.quiet:
        args.apply = True
        if (getattr(args, "target", "") or "").strip().lower() in ("", "all", "*"):
            args.target = "wb"
        args.yes = True

    # ---- 体检（只读，永不改盘） ----
    if getattr(args, "check", False):
        rc = run_check(args)
        _pause_on_exit()
        sys.exit(rc)

    # ---- 只清会话快照（显式要求才做，不连带跑一遍破甲） ----
    if (getattr(args, "clean_spill", False) or getattr(args, "purge_spill", False)) \
            and not any((args.apply, args.revert, args.dry_run)):
        rc = run_spill_clean(args)
        _pause_on_exit()
        sys.exit(rc)

    # ---- 双击 / 无参数：进交互菜单 ----
    if interactive and not any((args.apply, args.revert, args.dry_run)):
        menu(args)
        return

    if args.status or args.diagnose or not any((args.apply, args.revert, args.dry_run)):
        run_status(args)
        return
    if args.revert:
        if args.dry_run:
            # 预演语义优先 —— 不写盘、也不弹确认（确认是给真动作用的）
            say("  提示：同时给了 --revert 与 --dry-run → 只预演，绝不写盘。", "y")
        elif not args.yes and not QUIET:
            say("")
            if not _confirm("确认还原 %s ？" % args.target):
                say("  已取消。")
                return
        run_action(args, "revert")
        return
    if args.dry_run and not args.apply:
        run_action(args, "dry-run")
        return
    if args.apply:
        if args.dry_run:
            run_action(args, "dry-run")
            return
        if not args.yes and not QUIET:
            say("")
            if not _confirm("确认对 %s 执行破甲？" % args.target):
                say("  已取消。")
                return
        run_action(args, "apply")
        return

    menu(args)


if __name__ == "__main__":
    _rc = 0
    try:
        main()
        # 失败要让调用方看得见 —— 退出码非 0（守护任务、批处理、CI 都靠这个判断）
        _rc = 1 if ERRORS else 0
    finally:
        _pause_on_exit()
    sys.exit(_rc)
